mapper.select:
SELECT id AS image_id, object_key, thumbnail_object_key AS thumbnail_key
FROM community_image
WHERE post_id IS NULL
  AND created_at < #{createdBefore}
ORDER BY id
LIMIT #{limit}

mapper.delete:
DELETE FROM community_image
WHERE id = #{imageId}
  AND post_id IS NULL

mapper.select:
SELECT created_at
FROM community_image
WHERE member_id = #{memberId}
  AND post_id IS NULL
  AND created_at > #{createdAfter}
ORDER BY created_at
LIMIT #{limit}
